//! Which copies may be sent at all, which may be opened, and the copy held while the phone is away.

/// The same 10 minutes the outbox would hold it.
pub const HOLD_MS: i64 = 600_000;

/// Types password managers and similar apps mark their items with: an item carrying any of them is
/// never sent (threat model, "Never synced"). macOS: nspasteboard.org.
const PRIVATE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];
/// A copied file: the file manager adds its name as plain text, which isn't the user's text (SR-4-06).
const FILE_TYPES: [&str; 2] = ["public.file-url", "NSFilenamesPboardType"];

pub fn is_private(types: &[String]) -> bool {
    types.iter().any(|t| PRIVATE_TYPES.contains(&t.as_str()))
}

/// Whether an item with these types may be sent at all: not private, not a file.
pub fn sendable(types: &[String]) -> bool {
    !is_private(types) && !types.iter().any(|t| FILE_TYPES.contains(&t.as_str()))
}

/// The web address a clip may be opened as, only when the whole clip is one: a single http(s) URL
/// with a host and nothing around it, so what opens is what's shown (SR-10-03).
pub fn openable_url(text: &str) -> Option<&str> {
    // Printable ASCII only: no spaces, controls, zero-width or bidi characters can make what
    // opens differ from what's shown
    if !text.bytes().all(|b| b.is_ascii_graphic()) {
        return None;
    }
    let rest = text
        .strip_prefix("https://")
        .or_else(|| text.strip_prefix("http://"))?;
    let host = rest.split(['/', '?', '#']).next()?;
    let host = host.rsplit('@').next()?;
    (!host.is_empty() && !host.starts_with(':')).then_some(text)
}

/// The latest copy made while the phone was unreachable (SR-4-03). It's sent when the phone is
/// back only if sync is still on, it's for the same phone, and it isn't stale.
#[derive(Debug, Default)]
pub struct ClipQueue<T> {
    held: Option<(T, i64)>,
}

impl<T> ClipQueue<T> {
    pub fn is_empty(&self) -> bool {
        self.held.is_none()
    }

    /// Replaces anything held: only the latest copy matters.
    pub fn hold(&mut self, item: T, at_ms: i64) {
        self.held = Some((item, at_ms));
    }

    /// Sync turned off, or the phone changed: what was held must never go.
    pub fn clear(&mut self) {
        self.held = None;
    }

    /// What to send now the phone is back, if anything. Always empties the queue.
    pub fn take(&mut self, now_ms: i64, sync_on: bool) -> Option<T> {
        let (item, at) = self.held.take()?;
        (sync_on && now_ms - at <= HOLD_MS).then_some(item)
    }
}
